//! The server's signed station config fixture (`tests/fixtures/station_config/`,
//! made by `app/services/station_config_service.py`, regenerated byte for byte
//! by `tests/test_station_config_fixture.py`) verifies with this crate's
//! verifier, and its line 1 is already this crate's canonical JSON.

use chrono::{TimeZone, Utc};
use digitva_bundle::{ActingRole, BundleError, StationSigningKey, VerifiedStationConfig};
use digitva_text::to_jcs_string;
use std::path::PathBuf;

const DEVICE_ID: &str = "0b8d6c2e-1f3a-4c5b-9d7e-8f9a0b1c2d3e";

fn fixture(name: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../tests/fixtures/station_config")
        .join(name);
    std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()))
}

#[test]
fn server_fixture_verifies() {
    let text = fixture("station_config.signed");
    let verified = VerifiedStationConfig::parse_and_verify(&text, DEVICE_ID, None).expect("verifies");
    let cfg = &verified.config;
    assert_eq!(cfg.device_id, DEVICE_ID);
    assert_eq!(cfg.server_signing_key.signing_key_id, "334b2b6b54b0d965");
    assert_eq!(cfg.custodian.as_ref().unwrap().name, "Dr. Ren\u{e9}e Sharma");
    assert_eq!(cfg.custodian.as_ref().unwrap().verified_by_user_id, 1);
    assert_eq!(cfg.roster.len(), 2);
    assert_eq!(cfg.roster[0].user_id, 7);
    assert_eq!(cfg.roster[1].roles[0].role, ActingRole::StationSupervisor);
    assert!(!cfg.roster[1].active);
    assert_eq!(cfg.designations.len(), 4);
    assert_eq!(cfg.purge.len(), 1);
    assert_eq!(cfg.projects[0].project_id, "TST001");
    assert_eq!(cfg.projects[0].sealed_field_ids.len(), 19);
    assert!(cfg.projects[0].consent.is_some());
    let options = cfg.projects[0].form_options.as_ref().expect("form_options");
    assert_eq!(options["definition_sha256"], "88184fc7afb460b846ab16a40fc327f07047b02d56fd7a985900515a8df81291");
    assert_eq!(cfg.projects[0].translations["hi"]["version"], 6);
    assert_eq!(cfg.projects[0].coding_mode, Some(Some("icd11_doris".to_string())));
    assert_eq!(verified.issued_at, Utc.with_ymd_and_hms(2026, 10, 21, 9, 30, 0).unwrap());
}

#[test]
fn server_fixture_verifies_under_the_pinned_server_key() {
    let text = fixture("station_config.signed");
    let key = StationSigningKey::from_base64url_secret(&fixture("test_server_signing_key")).unwrap();
    assert_eq!(key.signing_key_id(), "334b2b6b54b0d965");
    VerifiedStationConfig::parse_and_verify(&text, DEVICE_ID, Some(&key.public_key_bytes())).expect("verifies");
    let other = StationSigningKey::from_secret_bytes(&[7u8; 32]);
    assert_eq!(
        VerifiedStationConfig::parse_and_verify(&text, DEVICE_ID, Some(&other.public_key_bytes())).unwrap_err(),
        BundleError::StationConfigSignatureInvalid
    );
}

#[test]
fn server_line_one_is_rust_canonical_json() {
    let text = fixture("station_config.signed");
    let line1 = text.split('\n').next().unwrap();
    let value: serde_json::Value = serde_json::from_str(line1).unwrap();
    assert_eq!(to_jcs_string(&value).unwrap(), line1);
}

#[test]
fn tampered_server_fixture_is_refused() {
    let text = fixture("station_config.signed").replace("\"active\":false", "\"active\":true");
    assert_eq!(
        VerifiedStationConfig::parse_and_verify(&text, DEVICE_ID, None).unwrap_err(),
        BundleError::StationConfigSignatureInvalid
    );
    let other_device = "00000000-0000-4000-8000-000000000000";
    assert!(matches!(
        VerifiedStationConfig::parse_and_verify(&fixture("station_config.signed"), other_device, None),
        Err(BundleError::StationConfigDeviceMismatch { .. })
    ));
}

#[test]
fn project_coding_mode_tells_null_from_absent() {
    let parse = |extra: &str| -> digitva_bundle::StationProjectConfig {
        serde_json::from_str(&format!(r#"{{"project_id":"P1"{extra}}}"#)).unwrap()
    };
    assert_eq!(parse("").coding_mode, None);
    assert_eq!(parse(r#","coding_mode":null"#).coding_mode, Some(None));
    assert_eq!(parse(r#","coding_mode":"icd10""#).coding_mode, Some(Some("icd10".to_string())));
    // Absent stays absent when written back; null is written as null.
    assert!(!serde_json::to_string(&parse("")).unwrap().contains("coding_mode"));
    assert!(serde_json::to_string(&parse(r#","coding_mode":null"#)).unwrap().contains(r#""coding_mode":null"#));
}
